package com.studenttong.mobile;
import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;
public final class Ui {
 public static final int BLUE=0xff3478e5,BG=0xfff5f7fb,TEXT=0xff202938,MUTED=0xff87909f,GREEN=0xff22a06b,RED=0xffe05252;
 public static int dp(Context c,int n){return (int)(n*c.getResources().getDisplayMetrics().density+.5f);}
 public static GradientDrawable bg(Context c,int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(c,radius));return d;}
 public static LinearLayout col(Context c){LinearLayout l=new LinearLayout(c);l.setOrientation(1);return l;}public static LinearLayout row(Context c){return new LinearLayout(c);}
 public static TextView text(Context c,String s,int size){TextView t=new TextView(c);t.setText(s);t.setTextSize(size);t.setTextColor(TEXT);t.setPadding(dp(c,3),dp(c,5),dp(c,3),dp(c,5));return t;}
 public static Button button(Context c,String s,Runnable action){Button b=new Button(c);b.setText(s);b.setTextSize(13);b.setAllCaps(false);b.setTextColor(BLUE);b.setMinWidth(0);b.setMinimumWidth(0);b.setMinHeight(dp(c,42));b.setMinimumHeight(dp(c,42));b.setPadding(dp(c,10),dp(c,4),dp(c,10),dp(c,4));b.setStateListAnimator(null);b.setBackground(new RippleDrawable(android.content.res.ColorStateList.valueOf(0x203478e5),bg(c,Color.WHITE,12),null));b.setOnClickListener(v->action.run());return b;}
 public static void primary(Button b){b.setTextColor(Color.WHITE);b.setBackground(bg(b.getContext(),BLUE,12));}
 public static void add(LinearLayout r,View v){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.setMargins(dp(r.getContext(),3),dp(r.getContext(),3),dp(r.getContext(),3),dp(r.getContext(),3));r.addView(v,p);}
 public static LinearLayout card(LinearLayout parent){Context c=parent.getContext();LinearLayout l=col(c);l.setPadding(dp(c,14),dp(c,10),dp(c,14),dp(c,10));l.setBackground(bg(c,Color.WHITE,16));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(c,6),0,dp(c,8));parent.addView(l,p);return l;}
 public static TextView badge(Context c,String s){TextView t=text(c,s,12);int color=s.contains("异常")||s.contains("失败")?RED:s.contains("完成")||s.contains("运行中")?GREEN:s.contains("暂停")||s.contains("停止")?MUTED:BLUE;t.setTextColor(color);t.setBackground(bg(c,(color&0xffffff)|0x15000000,8));return t;}
 public static void window(Activity a){a.getWindow().setStatusBarColor(BG);a.getWindow().setNavigationBarColor(Color.WHITE);a.getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);}
 public static class Icon extends Drawable {final int index,color;final Paint p=new Paint(3);public Icon(int i,int c){index=i;color=c;}public void draw(Canvas canvas){canvas.save();canvas.translate(getBounds().left,getBounds().top);canvas.scale(getBounds().width()/24f,getBounds().height()/24f);p.setColor(color);p.setStrokeWidth(1.7f);p.setStyle(Paint.Style.STROKE);p.setStrokeJoin(Paint.Join.ROUND);p.setStrokeCap(Paint.Cap.ROUND);if(index==0){canvas.drawRoundRect(3,4,21,20,2,2,p);Path path=new Path();path.moveTo(10,8);path.lineTo(16,12);path.lineTo(10,16);path.close();canvas.drawPath(path,p);}else if(index==1){canvas.drawRoundRect(5,4,20,21,2,2,p);canvas.drawLine(8,9,17,9,p);canvas.drawLine(8,13,17,13,p);canvas.drawLine(8,17,14,17,p);}else if(index==2){canvas.drawCircle(12,9,5,p);Path path=new Path();path.moveTo(7,12);path.lineTo(12,21);path.lineTo(17,12);canvas.drawPath(path,p);canvas.drawCircle(12,9,1.4f,p);}else if(index==3){canvas.drawRoundRect(3,4,21,20,2,2,p);canvas.drawLine(12,4,12,20,p);canvas.drawLine(6,8,9,8,p);canvas.drawLine(15,8,18,8,p);}else{canvas.drawCircle(12,12,7,p);canvas.drawCircle(12,12,2.4f,p);for(int i=0;i<8;i++){double n=i*Math.PI/4;canvas.drawLine((float)(12+8*Math.cos(n)),(float)(12+8*Math.sin(n)),(float)(12+10*Math.cos(n)),(float)(12+10*Math.sin(n)),p);}}canvas.restore();}public void setAlpha(int a){p.setAlpha(a);}public void setColorFilter(ColorFilter f){p.setColorFilter(f);}public int getOpacity(){return PixelFormat.TRANSLUCENT;}}
}
